fn int_param(i: usize) -> IntParam {
    let d = &PARAMS[i];
    let mut p = IntParam::new(d.name, d.default.round() as i32, IntRange::Linear { min: d.min as i32, max: d.max as i32 });
    if d.hidden {
        p = p.hide();
    }
    if d.labels.is_empty() {
        p
    } else {
        let min = d.min as i32;
        let labels = d.labels;
        p.with_value_to_string(Arc::new(move |v| labels.get((v - min) as usize).copied().unwrap_or("?").to_string()))
            .with_string_to_value(Arc::new(move |s| labels.iter().position(|l| l.eq_ignore_ascii_case(s.trim())).map(|i| i as i32 + min)))
    }
}

fn float_param(i: usize) -> FloatParam {
    let d = &PARAMS[i];
    let p = FloatParam::new(d.name, d.default, FloatRange::Linear { min: d.min, max: d.max })
        .with_step_size(0.01)
        .with_value_to_string(formatters::v2s_f32_rounded(2));
    if d.hidden {
        p.hide()
    } else {
        p
    }
}

